//! INF-20, test only: instructions that read (or point into) the first bytes of function entries, from
//! `catalog/code-data-reads.csv` (generated by `tools/catalog/code_data_reads.py` over every code
//! section: game `.text`, `_rwcseg`, the no-CD `.text`, `.init`, the executable `.data`, `.HOODLUM`).
//!
//! sa-hook's install test (`table::tests::every_hook_installs_on_the_exe`) fails for a hook whose
//! changed bytes such an instruction sees, unless it is an absolute read that [`crate::keycells`]
//! redirects to a copy of the original dword. What each redirected reader decodes is listed in
//! `docs/re/l2-oracle.md` ("Hooked code bytes read as data").

use crate::keycells::READERS;
use crate::table::Kind;

/// One row of `catalog/code-data-reads.csv`.
#[derive(Debug, Clone)]
pub struct Row {
    pub reader: u32,
    pub len: u8,
    pub insn: String,
    pub kind: String,
    pub disp_off: u8,
    pub target: u32,
    pub size: u32,
    /// Decodes in line from a `pushfd`/`stc`/`clc` (protection chunk shape).
    pub chunk: bool,
    /// Reached by a linear decode from the enclosing function start.
    pub sweep: bool,
}

fn hex(s: &str) -> u32 {
    u32::from_str_radix(s.trim_start_matches("0x"), 16).unwrap()
}

pub fn rows() -> Vec<Row> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let csv = std::fs::read_to_string(root.join("catalog/code-data-reads.csv")).unwrap();
    let mut out = Vec::new();
    for l in csv.lines().skip(1) {
        // reader,section,len,insn,kind,disp_off,target,size,entry,entry_off,chunk,sweep;
        // insn is quoted when it holds commas
        let (head, insn, tail) = match l.find('"') {
            Some(q) => {
                let e = q + 1 + l[q + 1..].find('"').unwrap();
                (&l[..q], &l[q + 1..e], &l[e + 2..])
            }
            None => {
                let f: Vec<&str> = l.splitn(5, ',').collect();
                let n = f[0].len() + f[1].len() + f[2].len() + 3;
                (&l[..n], f[3], f[4])
            }
        };
        let h: Vec<&str> = head.trim_end_matches(',').split(',').collect();
        let t: Vec<&str> = tail.split(',').collect();
        out.push(Row {
            reader: hex(h[0]),
            len: h[2].parse().unwrap(),
            insn: insn.to_string(),
            kind: t[0].to_string(),
            disp_off: t[1].parse().unwrap(),
            target: hex(t[2]),
            size: t[3].parse().unwrap(),
            chunk: t[6] == "1",
            sweep: t[7] == "1",
        });
    }
    out
}

/// The code bytes a hook changes: the rel32 of a `.HOODLUM` stub (its `E9` stays), or the
/// relocated entry (whole instructions covering 5 bytes, as `win::install_one` computes it).
pub fn changed(exe: &crate::testexe::Exe, addr: u32, kind: Kind) -> (u32, u32) {
    match kind {
        Kind::HoodlumStub => (addr + 1, addr + 5),
        Kind::Inline => {
            let consumed = crate::x86::relocate_keep_return(exe.bytes(addr, 32), addr, 0x1000_0000, 5)
                .map(|r| r.consumed as u32)
                .unwrap_or(16);
            (addr, addr + consumed)
        }
    }
}

/// Every instruction of the table that sees bytes in `lo..hi` and is not redirected by
/// [`READERS`]: a memory operand or an immediate address overlapping the range. Rows that decode
/// neither in a protection chunk nor on a linear sweep (decodes from the middle of another
/// instruction) do not count.
pub fn unredirected(rows: &[Row], lo: u32, hi: u32) -> Vec<String> {
    rows.iter()
        .filter(|r| r.target < hi && lo < r.target + r.size && (r.chunk || r.sweep))
        .filter(|r| {
            !(r.kind == "mem-abs" && READERS.iter().any(|k| k.at == r.reader && k.key == r.target))
        })
        .map(|r| {
            format!(
                "{:#x} `{}` ({}) sees {:#x}+{}",
                r.reader, r.insn, r.kind, r.target, r.size
            )
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use iced_x86::{Decoder, DecoderOptions};

    use super::{changed, rows, unredirected};
    use crate::keycells::READERS;
    use crate::table::Kind;

    #[test]
    fn readers_match_the_exe_and_the_table() {
        let Some(exe) = crate::testexe::load() else { return };
        let table = rows();
        for r in READERS {
            assert_eq!(exe.bytes(r.at, 6), &r.insn[..], "{:#x}", r.at);
            let d = r.disp_off as usize;
            assert_eq!(u32::from_le_bytes(r.insn[d..d + 4].try_into().unwrap()), r.key);
            assert_eq!(
                u32::from_le_bytes(exe.bytes(r.key, 4).try_into().unwrap()),
                r.value
            );
            assert!(
                table.iter().any(|t| t.reader == r.at
                    && t.kind == "mem-abs"
                    && t.target == r.key
                    && t.disp_off == r.disp_off
                    && t.chunk),
                "{:#x} is not a protection read in catalog/code-data-reads.csv",
                r.at
            );
        }
    }

    /// The table matches the exe: each row decodes to an instruction of that length whose 32-bit field
    /// at `disp_off` is the target (catches a stale table or one generated from another exe).
    #[test]
    fn table_matches_the_exe() {
        let Some(exe) = crate::testexe::load() else { return };
        let table = rows();
        assert!(table.len() > 1000, "{}", table.len());
        for r in &table {
            let mut dec =
                Decoder::with_ip(32, exe.bytes(r.reader, 16), r.reader as u64, DecoderOptions::NONE);
            let i = dec.decode();
            assert_eq!(i.len(), r.len as usize, "{:#x}", r.reader);
            let b = exe.bytes(r.reader + r.disp_off as u32, 4);
            assert_eq!(
                u32::from_le_bytes(b.try_into().unwrap()),
                r.target,
                "{:#x}",
                r.reader
            );
        }
    }

    /// The redirects themselves rewrite 4 bytes of protection code (each reader's `disp32`); no dword
    /// anywhere in the code sections (any alignment) points into those bytes.
    #[test]
    fn redirected_operands_are_not_read_as_data() {
        let Some(exe) = crate::testexe::load() else { return };
        for (va, data) in exe.code_sections() {
            for p in 0..data.len().saturating_sub(3) {
                let v = u32::from_le_bytes([data[p], data[p + 1], data[p + 2], data[p + 3]]);
                for r in READERS {
                    let lo = r.at + r.disp_off as u32;
                    assert!(
                        !(lo.saturating_sub(3)..lo + 4).contains(&v),
                        "{:#x} holds {v:#x}: points into the redirected operand of {:#x}",
                        va + p as u32,
                        r.at
                    );
                }
            }
        }
    }

    /// Negative test of the install check: a hook on an entry the protection reads (0x55C410 read at
    /// 0x4017B4, 0x563470 read at 0x4013A2, both unregistered) is rejected, and so would be
    /// 0x410860 (`CColStore::LoadCollision`, read at 0x401E46) without its redirect.
    #[test]
    fn a_hook_on_a_read_entry_is_rejected() {
        let Some(exe) = crate::testexe::load() else { return };
        let table = rows();
        let (lo, hi) = changed(&exe, 0x55C410, Kind::Inline);
        let hits = unredirected(&table, lo, hi);
        assert!(hits.iter().any(|h| h.starts_with("0x4017b4 ")), "{hits:?}");
        let (lo, hi) = changed(&exe, 0x563470, Kind::Inline);
        let hits = unredirected(&table, lo, hi);
        assert!(hits.iter().any(|h| h.starts_with("0x4013a2 ")), "{hits:?}");
        let (lo, hi) = changed(&exe, 0x410860, Kind::HoodlumStub);
        assert_eq!(unredirected(&table, lo, hi), Vec::<String>::new());
        let raw: Vec<u32> = table
            .iter()
            .filter(|r| r.target < hi && lo < r.target + r.size && r.chunk)
            .map(|r| r.reader)
            .collect();
        assert_eq!(raw, vec![0x401E46]);
    }
}
